/** Evaluator-only hidden truth generated by truth.py, and deterministic noise shared by the simulator. */
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { z } from 'zod'

const variety = z.object({ variety: z.number().int().min(1).max(4), r0: z.number(), lightOpt: z.number(), lightWidth: z.number(),
  irrigationOpt: z.number(), a1: z.number(), a3: z.number(), a12: z.number(), tempOpt: z.number() })
const contamination = z.object({ event: z.string(), onset: z.number().int(), hypotheses: z.array(z.enum(['inlet', 'membrane', 'seal'])).min(1),
  deltaInlet: z.number(), membraneRemoval: z.number(), deltaSeal: z.number(), lubricantRatio: z.number(),
  decoyModule: z.enum(['reservoir', 'filter', 'pump']), decoyOffset: z.number(), decoyOnset: z.number().int() })

export const truthSchema = z.object({
  version: z.literal(2), seed: z.number().int().positive(), load: z.enum(['L1', 'L2', 'L3', 'L4']), horizon: z.number().int().positive(), solTicks: z.number().int().positive(),
  settings: z.object({ deadlineFactor: z.number(), archiveScale: z.number(), dropout: z.number(), tasks: z.array(z.string()) }),
  water: z.object({ reservoir: z.number(), removal: z.number(), pumpIncrement: z.number(), k4: z.number(), kMinus10: z.number(), k22: z.number() }),
  bias: z.object({ confirmV1: z.number(), extractionA2: z.number() }),
  lots: z.object({ A1: z.string(), A2: z.string(), A3: z.string(), B: z.string(), medium: z.string() }),
  crops: z.object({ varieties: z.array(variety).length(4), individual: z.record(z.string(), z.number()), co2Half: z.number() }),
  energy: z.object({ dustRate: z.number(), battery: z.number(), peak: z.number(), cellFailure: z.object({ onset: z.number().int(), fraction: z.number() }).nullable() }),
  storms: z.array(z.object({ event: z.string(), onset: z.number().int(), duration: z.number().int(), factor: z.number() })),
  contamination: z.array(contamination),
  drift: z.array(z.object({ chamber: z.string(), channel: z.enum(['temperature', 'moisture']), rate: z.number(), onset: z.number().int() })),
  pathogen: z.object({ onset: z.number().int(), index: z.array(z.string()).min(1), lambda: z.number() }),
  wear: z.record(z.string(), z.object({ initial: z.number(), perUse: z.number() })),
  leak: z.object({ chamber: z.string(), point: z.enum(['door', 'duct', 'panel']), onset: z.number().int() }).nullable(),
  faults: z.array(z.object({ event: z.string(), deviceId: z.string(), tick: z.number().int() })),
  recall: z.object({ event: z.string(), tick: z.number().int(), lot: z.literal('A2') }).nullable(),
  methodUpdate: z.object({ event: z.string(), tick: z.number().int() }),
  incidents: z.array(z.object({ id: z.string(), onset: z.number().int() })),
})
export type Truth = z.infer<typeof truthSchema>
export type Contamination = Truth['contamination'][number]
export type Variety = Truth['crops']['varieties'][number]

export const archiveAnswersSchema = z.object({ Q1: z.number(), Q2: z.number(), Q3: z.number(), Q4: z.record(z.string(), z.number()),
  Q5: z.record(z.string(), z.number()), Q6: z.number(), Q7: z.number(), Q8: z.number() })
export type ArchiveAnswers = z.infer<typeof archiveAnswersSchema>

/** Load the hidden truth file written by the installer.
 * @param path Evaluator-side truth.json.
 * @returns Validated truth.
 */
export function loadTruth(path: string): Truth { return truthSchema.parse(JSON.parse(readFileSync(path, 'utf8'))) }

/** Deterministic uniform number in [0, 1) from any identity parts. */
export function unit(...parts: (string | number)[]): number {
  const digest = createHash('sha256').update(parts.join('|')).digest()
  return digest.readUIntBE(0, 6) / 2 ** 48
}
/** Deterministic standard normal draw from identity parts. */
export function normal(...parts: (string | number)[]): number {
  const a = Math.max(unit(...parts, 'a'), 1e-12), b = unit(...parts, 'b')
  return Math.sqrt(-2 * Math.log(a)) * Math.cos(2 * Math.PI * b)
}

export const CHAMBERS = ['incubator-1', 'incubator-2', 'incubator-3', 'incubator-4'] as const
export const CROP_IDS = CHAMBERS.flatMap((_, k) => [1, 2, 3, 4].map(v => `crop-${k + 1}-${v}`))
export const varietyOf = (cropId: string) => Number(cropId.split('-').at(-1))
export const chamberOf = (cropId: string) => `incubator-${cropId.split('-')[1]}`

/** Crop growth response for one variety, as defined in spec section 2.2. */
export function growthRate(truth: Truth, cropId: string, input: { light: number; nutrient: number; irrigation: number; co2: number; temperature: number }) {
  const v = truth.crops.varieties[varietyOf(cropId) - 1]!
  const fL = Math.exp(-(((input.light - v.lightOpt) / v.lightWidth) ** 2))
  const di = (input.irrigation - v.irrigationOpt) / 50
  const fNI = Math.max(0, 1 + v.a1 * (input.nutrient - 1) - v.a3 * di * di + v.a12 * (input.nutrient - 1) * di)
  const fC = (input.co2 / (input.co2 + truth.crops.co2Half)) / (800 / (800 + truth.crops.co2Half))
  const fT = Math.exp(-(((input.temperature - v.tempOpt) / 6) ** 2))
  return v.r0 * (truth.crops.individual[cropId] ?? 1) * fL * fNI * fC * fT
}

/** Water degradation rate at a storage temperature, log-linear between the three truth points. */
export function decayRate(truth: Truth, temperature: number) {
  const points: [number, number][] = [[-10, truth.water.kMinus10], [4, truth.water.k4], [22, truth.water.k22]]
  if (temperature <= points[0]![0]) return points[0]![1]
  if (temperature >= points[2]![0]) return points[2]![1]
  const [lower, upper] = temperature <= 4 ? [points[0]!, points[1]!] : [points[1]!, points[2]!]
  const fraction = (temperature - lower[0]) / (upper[0] - lower[0])
  return Math.exp(Math.log(lower[1]) + fraction * (Math.log(upper[1]) - Math.log(lower[1])))
}
